<?php declare(strict_types=1);
use Kulturhus\Native\Language\RoleMessages;
use Kulturhus\Verein\Settings\{RoleDraft,RoleInput};

$roleReadableIssues=['Die ursprüngliche Fassung ist nicht mehr aktuell.'=>'Eine andere Änderung wurde gespeichert. Lade den aktuellen Stand und prüfe deine Angaben.','Die ursprüngliche persönliche Zuordnung ist nicht mehr aktuell.'=>'Die Zuordnung wurde inzwischen geändert. Lade den aktuellen Stand und prüfe deine Auswahl.'];
$rt=static fn(string $source):string=>RoleMessages::text($roleReadableIssues[$source]??$source,$roleMessages);
$rf=static function(string $source,array $values)use($rt):string{$replace=[];foreach($values as$key=>$value)$replace['{'.$key.'}']=(string)$value;return strtr($rt($source),$replace);};
$roleControls=['edit','new_role','role_user','roles_q','roles_page','role_users_q','role_users_page','role_receipts_query','role_receipts_page','role_receipt','role_draft'];
$roleRoute=['view'=>'settings','tab'=>'roles'];foreach($roleControls as$field)if(is_string($_GET[$field]??null))$roleRoute[$field]=$_GET[$field];
$ru=static function(array $replace=[])use($roleRoute):string{$q=array_replace($roleRoute,$replace);return url(array_filter($q,static fn($value):bool=>$value!==null));};
$rh=static function(array $except=[])use($roleRoute):string{$h='';foreach($roleRoute as$key=>$value)if(!in_array($key,$except,true))$h.=hidden($key,$value);return$h;};
$roleActorNames=new \Kulturhus\Verein\ActorNames($db,(string)$_SESSION['actor']);
$scalar=static fn(mixed $value):string=>is_scalar($value)?(string)$value:(is_array($value)?json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE):'');
$roleTitles=['role-save'=>'Vereinsrolle bearbeiten','role-assign'=>'Vereinsrolle zuweisen','board-grant'=>'Vorstandsamt und Stimmrecht','identity-assign'=>'Persönliches Konto und Profil','identity-superuser'=>'Technische Kontoverwaltung'];
$roleRights=['members_access'=>'Mitglieder, Kontakte & Organisation','finance_access'=>'Finanzen, Spenden & Kassen','inventory_access'=>'Inventar & Lagerbestand','loans_access'=>'Ausleihen & Rückgaben','documents_access'=>'Allgemeine Orga-Dokumente','press_access'=>'Pressemitteilungen & Presseempfänger','minutes_access'=>'Protokolle für Mitglieder'];
$roleLevels=['none'=>'Kein Zugriff','read'=>'Lesen','write'=>'Bearbeiten'];
$roleBasic=['members'=>'Verwalter','treasurer'=>'Kassenwart','member'=>'Mitglied','editor'=>'Redaktion','admin'=>'Technische Administration'];
$roleField=static function(string $name,string $label,mixed $value,bool $multiline=false)use($rt,$scalar):void{?><label><?= e($rt($label)) ?><?php if($multiline): ?><textarea class="form-control" name="<?= e($name) ?>" rows="4"><?= e($scalar($value)) ?></textarea><?php else: ?><input class="form-control" name="<?= e($name) ?>" value="<?= e($scalar($value)) ?>"><?php endif ?></label><?php };
$roleSelect=static function(string $name,string $label,array $options,mixed $selected,bool $ownedLabels=false)use($rt,$scalar):void{$value=$scalar($selected);if(!array_key_exists($value,$options))$options=[$value=>$rt('Gewählte Zuordnung nicht verfügbar')]+$options;?><label><?= e($rt($label)) ?><select class="form-control" name="<?= e($name) ?>"><?php foreach($options as$key=>$labelText): ?><option value="<?= e((string)$key) ?>"<?= (string)$key===$value?' selected':'' ?>><?= e($ownedLabels?$rt($labelText):$labelText) ?></option><?php endforeach ?></select></label><?php };
$roleDescribe=static function(string $operation,array $input)use($rt,$scalar,$roleRights,$roleLevels,$roleActorNames):void{?>
<dl class="role-description"><?php if($operation==='role-save'):$data=is_array($input['data']??null)?$input['data']:[]; ?>
<dt><?= e($rt('Rollenname')) ?></dt><dd class="role-literal"><?= e($scalar($data['name']??'')) ?></dd><dt><?= e($rt('Beschreibung')) ?></dt><dd class="role-literal"><?= e($scalar($data['description']??'')) ?></dd>
<?php foreach($roleRights as$field=>$label): ?><dt><?= e($rt($label)) ?></dt><dd><?= e($rt($roleLevels[$scalar($data[$field]??'')]??'Ungültige Auswahl')) ?></dd><?php endforeach ?>
<dt><?= e($rt('Vereinseinstellungen und Rollen verwalten')) ?></dt><dd><?= e($rt(($data['settings_access']??'')==='1'?'Ja':'Nein')) ?></dd>
<dt><?= e($rt('Eigene Website-Bereichsfreigaben')) ?></dt><dd><?= e($rt(($data['website_custom']??'')==='1'?'Ja':'Nein')) ?></dd>
<?php foreach(\Kulturhus\Verein\EditorialPolicy::AREAS as$area=>$label): ?><dt><?= e($rt($label)) ?></dt><dd><?= e($rt($roleLevels[$scalar($data['website_levels'][$area]??'')]??'Ungültige Auswahl')) ?></dd><?php endforeach ?>
<?php else:foreach(['user'=>'Konto','account'=>'Persönliches Konto','role'=>'Gewählte Vereinsrolle','contact'=>'Gewähltes persönliches Profil','office'=>'Vorstandsamt','enabled'=>'Freigabe']as$field=>$label):if(!array_key_exists($field,$input))continue;$value=$scalar($input[$field]);if($field==='enabled')$value=$rt($value==='1'?'Ja':'Nein');elseif($field==='role'&&in_array($value,['__base__','__keep__'],true))$value=$rt($value==='__base__'?'Nur Grundrolle verwenden':'Bisherige Vereinsrolle beibehalten');elseif($value==='')$value=$rt('Keine Zuordnung');elseif(in_array($field,['user','account'],true))$value=$roleActorNames->label($value,$rt);elseif($field==='role')$value=$rt('Gewählte Vereinsrolle');elseif($field==='contact')$value=$rt('Gewähltes persönliches Profil'); ?><dt><?= e($rt($label)) ?></dt><dd class="role-literal"><?= e($value) ?></dd><?php endforeach;endif ?>
</dl><details class="role-technical-details"><summary><?=e($rt('Technische Details'))?></summary><p><?=e($rt('Ursprüngliche Fassung'))?>: <?=e($scalar($input['version']??''))?></p></details>
<?php };
$roleAccountState=static function(array $row):string{return $row['suspended']||!$row['active']?'blocked':(!$row['verified']?'pending':(!$row['account_active']?'blocked':'active'));};
$roleAccountMetadata=static function(array $row)use($rt,$roleAccountState):void{$status=$roleAccountState($row); ?><dl class="role-description"><dt><?= e($rt('Anmelde-E-Mail')) ?></dt><dd><?= e($row['email']) ?></dd><?php if(($row['login_name']??'')!==''&&$row['login_name']!==null): ?><dt><?= e($rt('Benutzername')) ?></dt><dd><?= e($row['login_name']) ?></dd><?php endif ?><dt><?= e($rt('Status des persönlichen Kontos')) ?></dt><dd data-role-native-status="<?= e($status) ?>"><?= e($rt(['pending'=>'Einladung offen','blocked'=>'Gesperrt','active'=>'Aktiv'][$status])) ?></dd></dl><?php };
$roleContext=static function(array $context)use($rt,$scalar,$roleAccountMetadata):void{?><dl class="role-description"><?php foreach(['target'=>'Aktuelles Konto','role'=>'Aktuelle gewählte Vereinsrolle','profile'=>'Aktuelles gewähltes Profil']as$field=>$label):if(empty($context[$field]))continue;$row=$context[$field]; ?><dt><?= e($rt($label)) ?></dt><dd><?= e($scalar($row['account_name']??$row['name']??$row['id']??'')) ?><?php if(isset($row['email'])): ?><br><?= e($row['email']) ?><?php endif ?></dd><?php endforeach ?><?php $board=$context['board']['board']??$context['subject']['board']??null;if($board): ?><dt><?= e($rt('Gespeichertes persönliches Vorstandsamt')) ?></dt><dd><?= e($rt($board['office'])) ?> · <?= e($rt($board['enabled']?'Bestätigt':'Nicht bestätigt')) ?></dd><?php endif ?></dl><?php if(isset($context['subject']['account_active']))$roleAccountMetadata($context['subject']); };
?>
<link rel="stylesheet" href="roles-native.css?v=1"><script defer src="roles-native.js?v=1"></script>
<section class="native-roles" data-native-roles>
<header class="page-heading"><h1><?= e($rt('Rollen & Rechte')) ?></h1><a class="btn btn-solid theme-primary" href="<?= e($ru(['new_role'=>'1','edit'=>null,'role_draft'=>null])) ?>#role-edit"><?= e($rt('Neue Rolle')) ?></a></header>
<?php if(!$roleState||!$roleState['actor']): ?><p role="alert"><?= e($rt('Eigene Rollenverwaltung erforderlich.')) ?></p></section><?php return;endif ?>
<?php if(!($managerSectionNavigationRendered??false)):$roleNavGroups=\Kulturhus\Verein\ManagerNavigation::sections(\Kulturhus\Verein\ManagerNavigation::settings(),$workspaceAccess); ?><nav class="module-tabs section-main-nav" aria-label="<?= e($rt('Einstellungsbereiche')) ?>"><?php foreach($roleNavGroups as$group): ?><a href="<?= e(url($group['routes'][0][1])) ?>"<?= $group['id']==='club'?' aria-current="true"':'' ?>><?= e($rt($group['label'])) ?></a><?php endforeach ?></nav>
<?php foreach($roleNavGroups as$group)if($group['id']==='club'): ?><nav class="module-tabs section-sub-nav" aria-label="<?= e($rt('Einstellungsbereiche – Unterseiten')) ?>"><?php foreach($group['routes']as[$label,$route]): ?><a href="<?= e(url($route)) ?>"<?= ($route['tab']??'')==='roles'?' aria-current="page"':'' ?>><?= e($rt($label)) ?></a><?php endforeach ?></nav><?php endif;endif ?>
<?php if($roleState['can_native']): ?><p><a class="btn btn-outline theme-secondary" href="/accounts"><?= e($rt('Einladungen und Kontosicherheit öffnen')) ?></a></p><?php endif ?>
<?php foreach($roleState['errors']as$field=>$message): ?><p role="alert" data-role-error="<?= e($field) ?>"><?= e($rt($message)) ?></p><?php endforeach ?>
<?php if($roleState['selected_user']):$u=$roleState['selected_user']; ?><section class="card role-selected-account" id="role-account"><h2><?= e($u['account_name']) ?></h2><p><?= e($rt($roleBasic[$u['role']]??$u['role'])) ?> · <?= e($u['role_name']??$rt('Nur Grundrolle')) ?> · <?= e($rt('Vereinszugang')) ?>: <?= e($rt($u['active']?'Aktiv':'Deaktiviert')) ?></p>
<details><summary><?= e($rt('Tatsächlich nutzbare Rechte')) ?></summary><?php if($roleState['effective']['available']??false): ?><dl class="role-description"><?php foreach($roleRights as$field=>$label): ?><dt><?= e($rt($label)) ?></dt><dd><?= e($rt($roleLevels[$roleState['effective']['actor'][$field]??'none'])) ?></dd><?php endforeach ?><dt><?= e($rt('Vereinseinstellungen und Rollen verwalten')) ?></dt><dd><?= e($rt($roleState['effective']['actor']['settings_access']?'Ja':'Nein')) ?></dd><?php foreach($roleState['effective']['website']as$area=>$level): ?><dt><?= e($rt(\Kulturhus\Verein\EditorialPolicy::AREAS[$area])) ?></dt><dd><?= e($rt($roleLevels[$level])) ?></dd><?php endforeach ?></dl><?php else: ?><p><?= e($rt('Konto nicht aktiv. Gespeicherte Zuordnungen bleiben getrennt erhalten.')) ?></p><?php endif ?></details>
