<?php if($roleState['receipt']):$receipt=$roleState['receipt']; ?><section class="card role-original" id="role-original" data-role-original="<?= e($receipt['key']) ?>"><h2><?= e($rt('Änderungsbestätigung')) ?></h2><p><?= e($rt($roleTitles[$receipt['operation']])) ?> · <strong><?= e($receipt['result']['label']) ?></strong></p><p><?= e($rt('Annehmendes Konto')) ?>: <?= e($roleActorNames->label($receipt['actor_id'],$rt)) ?></p><p><time><?= e($receipt['created_at']) ?></time></p><?php $roleDescribe($receipt['operation'],$receipt['input']);$roleContext($receipt['context']); ?><details class="role-technical-details"><summary><?=e($rt('Technische Details'))?></summary><p><?= e($rt('Diese Bestätigung zeigt die erste angenommene Änderung. Spätere Änderungen ersetzen sie nicht.')) ?></p><p class="role-proof"><?=e($receipt['key'])?></p><p class="role-proof">SHA-256: <?= e($receipt['sha256']) ?></p><a class="btn btn-outline theme-secondary" data-role-original-download data-navigation-native href="<?= e($ru(['role_original'=>$receipt['key']])) ?>"><?= e($rt('Original als JSON herunterladen')) ?></a></details></section><?php endif ?>
<?php foreach(['roles'=>['roles_q','roles_page','Vereinsrollen','Rolle oder Beschreibung','Rollenseite'],'accounts'=>['role_users_q','role_users_page','Konten','Konto oder Vereinsrolle','Kontenseite'],'history'=>['role_receipts_query','role_receipts_page','Änderungsverlauf','Änderungen suchen','Änderungsseite']]as$part=>$def):[$qfield,$pfield,$title,$searchLabel,$pageLabel]=$def;$listing=$roleState[$part];if(!$listing)continue; ?>
