<form method="get" class="role-search" data-live-search-page="<?= e($pfield) ?>"><?= $rh([$qfield,$pfield]) ?><?php $roleField($qfield,$searchLabel,$listing['query']); ?><button class="btn btn-outline theme-secondary"><?= e($rt('Suchen')) ?></button></form>
