<?php else: ?><a class="role-native-card" href="<?= e($ru(['role_receipt'=>$row['request_key']])) ?>#role-original"><strong><?= e($row['object_label']) ?></strong><span><?= e($rt($roleTitles[$row['operation']])) ?> · <?= e($row['created_at']) ?></span></a><?php endif;endforeach ?></div><?php elseif($listing['error']===''): ?><p><?= e($rt('Keine passenden Einträge.')) ?></p><?php endif ?>
